from typing import List

class Solution:
    def solveNQueens(self, n: int) -> List[List[str]]:
        result = []
        cols = []

        def valid() -> bool:
            for r1 in range(n):
                for r2 in range(r1 + 1, n):
                    c1, c2 = cols[r1], cols[r2]
                    if c1 == c2 or abs(r1 - r2) == abs(c1 - c2):
                        return False
            return True

        def dfs(row: int) -> None:
            if row == n:
                if valid():
                    result.append(["." * c + "Q" + "." * (n - c - 1) for c in cols])
                return
            for c in range(n):
                cols.append(c)
                dfs(row + 1)
                cols.pop()

        dfs(0)
        return result

